1	package responseapi
2	
3	import (
4		"encoding/json"
5		"fmt"
6		"strings"
7		"time"
8	
9		"github.com/openai/openai-go"
10	
11		"github.com/vllm-project/semantic-router/src/semantic-router/pkg/observability/logging"
12	)
13	
14	// Translator handles conversion between Response API and Chat Completions API.
15	type Translator struct{}
16	
17	// NewTranslator creates a new translator instance.
18	func NewTranslator() *Translator {
19		return &Translator{}
20	}
21	
22	// resolveInstructions returns the effective system instructions, falling back to
23	// the most recent non-empty instructions in the conversation history.
24	func resolveInstructions(req *ResponseAPIRequest, history []*StoredResponse) string {
25		if req.Instructions != "" {
26			return req.Instructions
27		}
28		for _, resp := range history {
29			if resp != nil && resp.Instructions != "" {
30				return resp.Instructions
31			}
32		}
33		return ""
34	}
35	
36	// buildHistoryMessages converts stored conversation history into chat messages.
37	func (t *Translator) buildHistoryMessages(history []*StoredResponse) []openai.ChatCompletionMessageParamUnion {
38		var msgs []openai.ChatCompletionMessageParamUnion
39		for _, resp := range history {
40			for _, item := range resp.Input {
41				msg, err := t.inputItemToMessage(item)
42				if err != nil {
43					logging.Warnf("Response API: skipping malformed history input item (role=%s): %v", item.Role, err)
44					continue
45				}
46				msgs = append(msgs, msg)
47			}
48			for _, item := range resp.Output {
49				msg, err := t.outputItemToMessage(item)
50				if err != nil {
51					logging.Warnf("Response API: skipping malformed history output item (type=%s): %v", item.Type, err)
52					continue
53				}
54				msgs = append(msgs, msg)
55			}
56		}
57		return msgs
58	}
59	
60	// TranslateToCompletionRequest converts a Response API request to Chat Completions request.
61	func (t *Translator) TranslateToCompletionRequest(
62		req *ResponseAPIRequest,
63		history []*StoredResponse,
64	) (*openai.ChatCompletionNewParams, error) {
65		var messages []openai.ChatCompletionMessageParamUnion
66	
67		if instructions := resolveInstructions(req, history); instructions != "" {
68			messages = append(messages, openai.ChatCompletionMessageParamUnion{
69				OfSystem: &openai.ChatCompletionSystemMessageParam{
70					Content: openai.ChatCompletionSystemMessageParamContentUnion{
71						OfString: openai.String(instructions),
72					},
73				},
74			})
75		}
76	
77		messages = append(messages, t.buildHistoryMessages(history)...)
78	
79		inputMessages, err := t.parseInput(req.Input)
80		if err != nil {
81			return nil, fmt.Errorf("failed to parse input: %w", err)
82		}
83		messages = append(messages, inputMessages...)
84	
85		completionReq := &openai.ChatCompletionNewParams{
86			Model:    req.Model,
87			Messages: messages,
88		}
89	
90		if req.Temperature != nil {
91			completionReq.Temperature = openai.Float(*req.Temperature)
92		}
93		if req.TopP != nil {
94			completionReq.TopP = openai.Float(*req.TopP)
95		}
96		if req.MaxOutputTokens != nil {
97			completionReq.MaxTokens = openai.Int(int64(*req.MaxOutputTokens))
98		}
99		if req.Stream {
100			completionReq.StreamOptions = openai.ChatCompletionStreamOptionsParam{
101				IncludeUsage: openai.Bool(true),
102			}
103		}
104	
105		if len(req.Tools) > 0 {
106			completionReq.Tools = t.convertTools(req.Tools)
107		}
108	
109		if req.ToolChoice != nil {
110			completionReq.ToolChoice = convertToolChoice(req.ToolChoice)
111		}
112	
113		return completionReq, nil
114	}
115	
116	// convertToolChoice maps the Response API tool_choice value (string or
117	// structured object) to the Chat Completions union parameter.
118	func convertToolChoice(v interface{}) openai.ChatCompletionToolChoiceOptionUnionParam {
119		switch tc := v.(type) {
120		case string:
121			return openai.ChatCompletionToolChoiceOptionUnionParam{
122				OfAuto: openai.String(tc),
123			}
124		default:
125			raw, err := json.Marshal(tc)
126			if err != nil {
127				return openai.ChatCompletionToolChoiceOptionUnionParam{}
128			}
129			var named openai.ChatCompletionNamedToolChoiceParam
130			if json.Unmarshal(raw, &named) == nil && named.Function.Name != "" {
131				return openai.ChatCompletionToolChoiceOptionUnionParam{
132					OfChatCompletionNamedToolChoice: &named,
133				}
134			}
135			return openai.ChatCompletionToolChoiceOptionUnionParam{}
136		}
137	}
138	
139	// TranslateToResponseAPIResponse converts a Chat Completions response to Response API response.
140	func (t *Translator) TranslateToResponseAPIResponse(
141		req *ResponseAPIRequest,
142		resp *openai.ChatCompletion,
143		previousResponseID string,
144	) *ResponseAPIResponse {
145		responseID := GenerateResponseID()
146		now := time.Now().Unix()
147	
148		output := []OutputItem{}
149		var outputText strings.Builder
150	
151		for _, choice := range resp.Choices {
152			msg := choice.Message
153	
154			if msg.Content != "" {
155				outputText.WriteString(msg.Content)
156				output = append(output, OutputItem{
157					Type:   ItemTypeMessage,
158					ID:     GenerateItemID(),
159					Role:   string(msg.Role),
160					Status: StatusCompleted,
161					Content: []ContentPart{{
162						Type: ContentTypeOutputText,
163						Text: msg.Content,
164					}},
165				})
166			}
167	
168			for _, tc := range msg.ToolCalls {
169				output = append(output, OutputItem{
170					Type:      ItemTypeFunctionCall,
171					ID:        GenerateItemID(),
172					CallID:    tc.ID,
173					Name:      tc.Function.Name,
174					Arguments: tc.Function.Arguments,
175					Status:    StatusCompleted,
176				})
177			}
178		}
179	
180		usage := &Usage{
181			InputTokens:  int(resp.Usage.PromptTokens),
182			OutputTokens: int(resp.Usage.CompletionTokens),
183			TotalTokens:  int(resp.Usage.TotalTokens),
184		}
185	
186		return &ResponseAPIResponse{
187			ID:                 responseID,
188			Object:             "response",
189			CreatedAt:          now,
190			Model:              resp.Model,
191			Status:             StatusCompleted,
192			Output:             output,
193			OutputText:         outputText.String(),
194			PreviousResponseID: previousResponseID,
195			ConversationID:     req.ConversationID,
196			Usage:              usage,
197			Instructions:       req.Instructions,
198			Metadata:           req.Metadata,
199			Temperature:        req.Temperature,
200			TopP:               req.TopP,
201			MaxOutputTokens:    req.MaxOutputTokens,
202			Tools:              req.Tools,
203			ToolChoice:         req.ToolChoice,
204		}
205	}
206	
207	// parseInput parses the input field which can be a string or array.
208	func (t *Translator) parseInput(input json.RawMessage) ([]openai.ChatCompletionMessageParamUnion, error) {
209		if len(input) == 0 {
210			return nil, fmt.Errorf("input is required")
211		}
212	
213		var inputStr string
214		if err := json.Unmarshal(input, &inputStr); err == nil {
215			return []openai.ChatCompletionMessageParamUnion{
216				userMessage(inputStr),
217			}, nil
218		}
219	
220		var items []InputItem
221		if err := json.Unmarshal(input, &items); err != nil {
222			return nil, fmt.Errorf("invalid input format: %w", err)
223		}
224	
225		var messages []openai.ChatCompletionMessageParamUnion
226		for _, item := range items {
227			msg, err := t.inputItemToMessage(item)
228			if err != nil {
229				continue
230			}
231			messages = append(messages, msg)
232		}
233	
234		return messages, nil
235	}
236	
237	// inputItemToMessage converts an InputItem to an SDK message union.
238	// Handles both plain string content and multimodal content arrays
239	// (text + image_url) by building the appropriate SDK union variant.
240	func (t *Translator) inputItemToMessage(item InputItem) (openai.ChatCompletionMessageParamUnion, error) {
241		role := item.Role
242		if role == "" {
243			role = RoleUser
244		}
245	
246		if len(item.Content) == 0 {
247			return messageForRole(role, ""), nil
248		}
249	
250		var contentStr string
251		if err := json.Unmarshal(item.Content, &contentStr); err == nil {
252			return messageForRole(role, contentStr), nil
253		}
254	
255		var parts []ContentPart
256		if err := json.Unmarshal(item.Content, &parts); err == nil {
257			if hasImageParts(parts) {
258				if role == RoleUser {
259					return userMessageWithParts(parts), nil
260				}
261				logging.Warnf("Response API: image content dropped for non-user role %q (OpenAI only supports images in user messages)", role)
262			}
263			return messageForRole(role, t.extractTextFromParts(parts)), nil
264		}
265	
266		return messageForRole(role, ""), nil
267	}
268	
269	// hasImageParts returns true if any part contains image content.
270	func hasImageParts(parts []ContentPart) bool {
271		for _, p := range parts {
272			if p.Type == ContentTypeInputImage && p.ImageURL != "" {
273				return true
274			}
275		}
276		return false
277	}
278	
279	// userMessageWithParts builds a user message with multimodal content parts.
280	func userMessageWithParts(parts []ContentPart) openai.ChatCompletionMessageParamUnion {
281		sdkParts := make([]openai.ChatCompletionContentPartUnionParam, 0, len(parts))
282		for _, p := range parts {
283			switch {
284			case (p.Type == ContentTypeInputText || p.Type == ContentTypeOutputText) && p.Text != "":
285				sdkParts = append(sdkParts, openai.ChatCompletionContentPartUnionParam{
286					OfText: &openai.ChatCompletionContentPartTextParam{Text: p.Text},
287				})
288			case p.Type == ContentTypeInputImage && p.ImageURL != "":
289				part := openai.ChatCompletionContentPartUnionParam{
290					OfImageURL: &openai.ChatCompletionContentPartImageParam{
291						ImageURL: openai.ChatCompletionContentPartImageImageURLParam{
292							URL: p.ImageURL,
293						},
294					},
295				}
296				if p.Detail != "" {
297					part.OfImageURL.ImageURL.Detail = p.Detail
298				}
299				sdkParts = append(sdkParts, part)
300			}
301		}
302		return openai.ChatCompletionMessageParamUnion{
303			OfUser: &openai.ChatCompletionUserMessageParam{
304				Content: openai.ChatCompletionUserMessageParamContentUnion{
305					OfArrayOfContentParts: sdkParts,
306				},
307			},
308		}
309	}
310	
311	// outputItemToMessage converts an OutputItem to an SDK message union.
312	func (t *Translator) outputItemToMessage(item OutputItem) (openai.ChatCompletionMessageParamUnion, error) {
313		switch item.Type {
314		case ItemTypeMessage:
315			content := ""
316			for _, part := range item.Content {
317				if part.Type == ContentTypeOutputText {
318					content += part.Text
319				}
320			}
321			return messageForRole(item.Role, content), nil
322	
323		case ItemTypeFunctionCall:
324			return openai.ChatCompletionMessageParamUnion{
325				OfAssistant: &openai.ChatCompletionAssistantMessageParam{
326					ToolCalls: []openai.ChatCompletionMessageToolCallParam{{
327						ID:   item.CallID,
328						Type: "function",
329						Function: openai.ChatCompletionMessageToolCallFunctionParam{
330							Name:      item.Name,
331							Arguments: item.Arguments,
332						},
333					}},
334				},
335			}, nil
336	
337		case ItemTypeFunctionCallOutput:
338			return openai.ChatCompletionMessageParamUnion{
339				OfTool: &openai.ChatCompletionToolMessageParam{
340					Content: openai.ChatCompletionToolMessageParamContentUnion{
341						OfString: openai.String(item.Output),
342					},
343					ToolCallID: item.CallID,
344				},
345			}, nil
346		}
347	
348		return openai.ChatCompletionMessageParamUnion{}, fmt.Errorf("unknown item type: %s", item.Type)
349	}
350	
