1	// Package anthropic - passthrough carrier for Anthropic-only request fields.
2	//
3	// The default request-body translation in this package takes an OpenAI-shape
4	// ChatCompletionNewParams and produces an Anthropic-shape MessageNewParams.
5	// Several Anthropic-only fields have no OpenAI representation (cache_control
6	// markers, top_k, metadata.user_id, multi-block system prompts with per-block
7	// markers, image content blocks, tool_result.is_error, tool_result with array
8	// content, anthropic-version, anthropic-beta). When those fields are present on
9	// the inbound request, today's translation silently drops them.
10	//
11	// AnthropicPassthrough is a per-request sidecar that the caller populates from
12	// the raw inbound body (or supplies directly when the upstream IR knows the
13	// shape) and ToAnthropicRequestBodyWithPassthrough consumes during rebuild.
14	// Every consumer treats a nil *AnthropicPassthrough as "no passthrough, use
15	// today's defaults", so existing callers remain byte-identical.
16	package anthropic
17	
18	import (
19		"fmt"
20	
21		"github.com/tidwall/gjson"
22	)
23	
24	// AnthropicPassthrough carries Anthropic-only request fields that have no
25	// OpenAI representation, so the outbound write path can replay them on the
26	// request body and headers. Lifetime is one request: built by the caller from
27	// the raw inbound body (or supplied directly by upstream IR), consumed by
28	// ToAnthropicRequestBodyWithPassthrough and BuildRequestHeadersWithPassthrough,
29	// then discarded.
30	type AnthropicPassthrough struct {
31		// AnthropicVersion is the inbound anthropic-version header value. Empty
32		// means "use the package default" (AnthropicAPIVersion).
33		AnthropicVersion string
34	
35		// AnthropicBeta is the inbound anthropic-beta header value, comma-separated
36		// per Anthropic convention. Empty means "do not emit".
37		AnthropicBeta string
38	
39		// TopK preserves the Anthropic top_k sampling parameter. nil means "not set
40		// on inbound; do not emit".
41		TopK *int64
42	
43		// MetadataUserID populates metadata.user_id on the outbound body. Empty
44		// means "do not emit".
45		MetadataUserID string
46	
47		// SystemBlocks preserves array-form system prompts. When non-empty,
48		// overrides the string-form system derived from OpenAI messages.
49		SystemBlocks []SystemBlock
50	
51		// CacheControl maps stable block IDs to cache_control markers. Block IDs
52		// match the JSON-path convention: "system[i]",
53		// "messages[i].content[j]", "tools[i]". The emitter applies markers
54		// best-effort: when the block exists on the outbound side, attach; when an
55		// upstream mutation removed the block, drop silently.
56		CacheControl map[string]CacheControlSpec
57	
58		// ToolResultErrors maps tool_call_id to the is_error flag, so the emitter
59		// can restore is_error: true on the matching outbound tool_result.
60		ToolResultErrors map[string]bool
61	
62		// ToolResultArrayContent maps tool_call_id to the preserved array content
63		// (text + image blocks) for tool_result blocks whose original content was
64		// an array rather than a plain string.
65		ToolResultArrayContent map[string][]ToolResultContentBlock
66	
67		// UserMessageImageBlocks maps user-message index to image blocks dropped by
68		// the OpenAI-side flatten. The emitter re-attaches them to the
69		// corresponding user message on the outbound side. Indices are counted
70		// against user messages only (i.e. index 0 is the first user message,
71		// regardless of any preceding system or assistant messages).
72		UserMessageImageBlocks map[int][]ImageBlock
73	}
74	
75	// SystemBlock represents one element of an array-form Anthropic system prompt.
76	type SystemBlock struct {
77		Text         string
78		CacheControl *CacheControlSpec
79	}
80	
81	// CacheControlSpec captures the Anthropic cache_control marker. Type is always
82	// "ephemeral" today; TTL is one of "", "5m", "1h".
83	type CacheControlSpec struct {
84		Type string
85		TTL  string
86	}
87	
88	// ToolResultContentBlock represents one block of a tool_result content array.
89	// Type is "text" or "image"; only the matching fields are populated.
90	type ToolResultContentBlock struct {
91		Type   string
92		Text   string
93		Source *ImageSource
94	}
95	
96	// ImageBlock represents a user-message image content block.
97	type ImageBlock struct {
98		Source ImageSource
99	}
100	
101	// ImageSource represents the source of an image content block. Type is
102	// "base64" or "url"; only the matching fields are populated.
103	type ImageSource struct {
104		Type      string
105		MediaType string
106		Data      string
107		URL       string
108	}
109	
110	// SetHeadersFromIncoming populates AnthropicVersion and AnthropicBeta from a
111	// case-insensitive lookup of the incoming request header map. Empty header
112	// values are ignored so the package default applies.
113	func (p *AnthropicPassthrough) SetHeadersFromIncoming(headers map[string]string) {
114		if p == nil || len(headers) == 0 {
115			return
116		}
117		for k, v := range headers {
118			if v == "" {
119				continue
120			}
121			switch lowerASCII(k) {
122			case "anthropic-version":
123				p.AnthropicVersion = v
124			case "anthropic-beta":
125				p.AnthropicBeta = v
126			}
127		}
128	}
129	
130	// lowerASCII lower-cases ASCII letters in s. HTTP header names are ASCII per
131	// RFC 7230, so strings.ToLower (which is Unicode-aware) is unnecessary
132	// overhead.
133	func lowerASCII(s string) string {
134		b := []byte(s)
135		for i := 0; i < len(b); i++ {
136			if b[i] >= 'A' && b[i] <= 'Z' {
137				b[i] += 'a' - 'A'
138			}
139		}
140		return string(b)
141	}
142	
143	// BuildPassthroughFromAnthropicBody parses the raw Anthropic-shape JSON body
144	// and returns a populated passthrough carrier. Lenient: malformed JSON or
145	// unrecognised shapes are silently skipped so the outbound path falls back to
146	// today's defaults rather than failing the request. Returns (nil, nil) when
147	// the input is empty.
148	func BuildPassthroughFromAnthropicBody(raw []byte) (*AnthropicPassthrough, error) {
149		if len(raw) == 0 {
150			return nil, nil
151		}
152		pt := &AnthropicPassthrough{}
153		captureSamplingAndMetadata(raw, pt)
154		captureSystemBlocks(raw, pt)
155		captureMessages(raw, pt)
156		captureTools(raw, pt)
157		return pt, nil
158	}
159	
160	func captureSamplingAndMetadata(raw []byte, pt *AnthropicPassthrough) {
161		if v := gjson.GetBytes(raw, "top_k"); v.Exists() && v.Type == gjson.Number {
162			k := v.Int()
163			pt.TopK = &k
164		}
165		if v := gjson.GetBytes(raw, "metadata.user_id"); v.Exists() && v.Type == gjson.String {
166			pt.MetadataUserID = v.String()
167		}
168	}
169	
170	func captureSystemBlocks(raw []byte, pt *AnthropicPassthrough) {
171		sys := gjson.GetBytes(raw, "system")
172		if !sys.IsArray() {
173			return
174		}
175		sys.ForEach(func(i, block gjson.Result) bool {
176			sb := SystemBlock{Text: block.Get("text").String()}
177			if cc := block.Get("cache_control"); cc.Exists() {
178				spec := parsePassthroughCacheControl(cc)
179				sb.CacheControl = &spec
180				pt.setCacheControl(fmt.Sprintf("system[%d]", i.Int()), spec)
181			}
182			pt.SystemBlocks = append(pt.SystemBlocks, sb)
183			return true
184		})
185	}
186	
187	func captureMessages(raw []byte, pt *AnthropicPassthrough) {
188		userMsgIndex := -1
189		gjson.GetBytes(raw, "messages").ForEach(func(mi, msg gjson.Result) bool {
190			isUser := msg.Get("role").String() == "user"
191			if isUser {
192				userMsgIndex++
193			}
194			msg.Get("content").ForEach(func(ci, content gjson.Result) bool {
195				captureContentBlock(pt, mi.Int(), ci.Int(), isUser, userMsgIndex, content)
196				return true
197			})
198			return true
199		})
200	}
201	
202	func captureContentBlock(pt *AnthropicPassthrough, mi, ci int64, isUser bool, userMsgIndex int, content gjson.Result) {
203		if cc := content.Get("cache_control"); cc.Exists() {
204			pt.setCacheControl(fmt.Sprintf("messages[%d].content[%d]", mi, ci), parsePassthroughCacheControl(cc))
205		}
206		switch content.Get("type").String() {
207		case "image":
208			if isUser {
209				if img, ok := parseImageBlock(content); ok {
210					pt.appendImageBlock(userMsgIndex, img)
211				}
212			}
213		case "tool_result":
214			captureToolResult(pt, content)
215		}
216	}
217	
218	func captureToolResult(pt *AnthropicPassthrough, content gjson.Result) {
219		id := content.Get("tool_use_id").String()
220		if id == "" {
221			return
222		}
223		if content.Get("is_error").Bool() {
224			pt.setToolResultError(id, true)
225		}
226		if c := content.Get("content"); c.IsArray() {
227			if blocks := parseToolResultBlocks(c); len(blocks) > 0 {
228				pt.setToolResultArrayContent(id, blocks)
229			}
230		}
231	}
232	
233	func captureTools(raw []byte, pt *AnthropicPassthrough) {
234		gjson.GetBytes(raw, "tools").ForEach(func(i, tool gjson.Result) bool {
235			if cc := tool.Get("cache_control"); cc.Exists() {
236				pt.setCacheControl(fmt.Sprintf("tools[%d]", i.Int()), parsePassthroughCacheControl(cc))
237			}
238			return true
239		})
240	}
241	
242	func parsePassthroughCacheControl(cc gjson.Result) CacheControlSpec {
243		spec := CacheControlSpec{Type: cc.Get("type").String()}
244		if spec.Type == "" {
245			spec.Type = "ephemeral"
246		}
247		if ttl := cc.Get("ttl").String(); ttl != "" {
248			spec.TTL = ttl
249		}
250		return spec
251	}
252	
253	func parseImageBlock(content gjson.Result) (ImageBlock, bool) {
254		source := content.Get("source")
255		if !source.Exists() {
256			return ImageBlock{}, false
257		}
258		src := parseImageSource(source)
259		if src.Type == "" {
260			return ImageBlock{}, false
261		}
262		return ImageBlock{Source: src}, true
263	}
264	
265	func parseImageSource(source gjson.Result) ImageSource {
266		srcType := source.Get("type").String()
267		switch srcType {
268		case "base64":
269			return ImageSource{
270				Type:      "base64",
271				MediaType: source.Get("media_type").String(),
272				Data:      source.Get("data").String(),
273			}
274		case "url":
275			return ImageSource{
276				Type: "url",
277				URL:  source.Get("url").String(),
278			}
279		}
280		return ImageSource{}
281	}
282	
283	func parseToolResultBlocks(content gjson.Result) []ToolResultContentBlock {
284		var blocks []ToolResultContentBlock
285		content.ForEach(func(_, block gjson.Result) bool {
286			switch block.Get("type").String() {
287			case "text":
288				blocks = append(blocks, ToolResultContentBlock{
289					Type: "text",
290					Text: block.Get("text").String(),
291				})
292			case "image":
293				src := parseImageSource(block.Get("source"))
294				if src.Type != "" {
295					blocks = append(blocks, ToolResultContentBlock{
296						Type:   "image",
297						Source: &src,
298					})
299				}
300			}
301			return true
302		})
303		return blocks
304	}
305	
306	func (p *AnthropicPassthrough) setCacheControl(id string, spec CacheControlSpec) {
307		if p.CacheControl == nil {
308			p.CacheControl = map[string]CacheControlSpec{}
309		}
310		p.CacheControl[id] = spec
311	}
312	
313	func (p *AnthropicPassthrough) setToolResultError(id string, isError bool) {
314		if p.ToolResultErrors == nil {
315			p.ToolResultErrors = map[string]bool{}
316		}
317		p.ToolResultErrors[id] = isError
318	}
319	
320	func (p *AnthropicPassthrough) setToolResultArrayContent(id string, blocks []ToolResultContentBlock) {
321		if p.ToolResultArrayContent == nil {
322			p.ToolResultArrayContent = map[string][]ToolResultContentBlock{}
323		}
324		p.ToolResultArrayContent[id] = blocks
325	}
326	
327	func (p *AnthropicPassthrough) appendImageBlock(userMsgIndex int, img ImageBlock) {
328		if p.UserMessageImageBlocks == nil {
329			p.UserMessageImageBlocks = map[int][]ImageBlock{}
330		}
331		p.UserMessageImageBlocks[userMsgIndex] = append(p.UserMessageImageBlocks[userMsgIndex], img)
332	}
