3	// This file contains the private helper functions that implement the
4	// OpenAI→Anthropic request body translation called by the public entry
5	// points ToAnthropicRequestBody and ToAnthropicRequestBodyWithPassthrough
6	// (in client.go). Keeping them here lets client.go stay focused on the
7	// public API surface and the symmetric response-path helpers.
8	package anthropic
9	
10	import (
11		"encoding/json"
