22	// resolveMaxTokens picks max_tokens with Anthropic's required default.
23	func resolveMaxTokens(req *openai.ChatCompletionNewParams) int64 {
24		switch {
25		case req.MaxCompletionTokens.Value > 0:
26			return req.MaxCompletionTokens.Value
27		case req.MaxTokens.Value > 0:
28			return req.MaxTokens.Value
29		default:
30			return DefaultMaxTokens
31		}
