34	// buildSystem returns the Anthropic system array. When pt carries
35	// SystemBlocks (array-form system from inbound), each block is emitted with
36	// its cache_control marker; otherwise it falls back to the string-form system
37	// derived from the OpenAI messages, preserving today's behaviour byte-for-byte.
38	func buildSystem(systemPrompt string, pt *AnthropicPassthrough) []anthropic.TextBlockParam {
39		if pt != nil && len(pt.SystemBlocks) > 0 {
40			out := make([]anthropic.TextBlockParam, 0, len(pt.SystemBlocks))
41			for _, sb := range pt.SystemBlocks {
42				block := anthropic.TextBlockParam{Text: sb.Text}
43				if sb.CacheControl != nil {
44					block.CacheControl = toSDKCacheControl(*sb.CacheControl)
45				}
46				out = append(out, block)
47			}
48			return out
49		}
50		if systemPrompt == "" {
51			return nil
52		}
53		return []anthropic.TextBlockParam{{Text: systemPrompt}}
54	}
