56	// applySampling sets temperature, top_p, and stop_sequences from the OpenAI
57	// request, plus top_k from the passthrough when present.
58	func applySampling(params *anthropic.MessageNewParams, req *openai.ChatCompletionNewParams, pt *AnthropicPassthrough) {
59		if req.Temperature.Valid() {
60			params.Temperature = anthropic.Float(req.Temperature.Value)
61		}
62		if req.TopP.Valid() {
63			params.TopP = anthropic.Float(req.TopP.Value)
64		}
65		if len(req.Stop.OfStringArray) > 0 {
66			params.StopSequences = req.Stop.OfStringArray
67		} else if req.Stop.OfString.Value != "" {
68			params.StopSequences = []string{req.Stop.OfString.Value}
69		}
70		if pt != nil && pt.TopK != nil {
71			params.TopK = anthropic.Int(*pt.TopK)
72		}
73	}
