75	// applyMetadata emits metadata.user_id from the passthrough when set, falling
76	// back to the OpenAI request's `user` field as the conventional mapping.
77	func applyMetadata(params *anthropic.MessageNewParams, req *openai.ChatCompletionNewParams, pt *AnthropicPassthrough) {
78		userID := ""
79		if pt != nil && pt.MetadataUserID != "" {
80			userID = pt.MetadataUserID
81		} else if req != nil && req.User.Valid() && req.User.Value != "" {
82			userID = req.User.Value
83		}
84		if userID == "" {
85			return
86		}
87		params.Metadata = anthropic.MetadataParam{UserID: anthropic.String(userID)}
