90	// applyToolsCacheControl attaches cache_control markers to tool definitions
91	// based on the `tools[i]` keys in the passthrough.
92	func applyToolsCacheControl(params *anthropic.MessageNewParams, pt *AnthropicPassthrough) {
93		if pt == nil || len(pt.CacheControl) == 0 {
94			return
95		}
96		for i := range params.Tools {
97			spec, ok := pt.CacheControl[fmt.Sprintf("tools[%d]", i)]
98			if !ok {
99				continue
100			}
101			if params.Tools[i].OfTool != nil {
102				params.Tools[i].OfTool.CacheControl = toSDKCacheControl(spec)
103			}
104		}
105	}
106	
107	// applyMessagesCacheControl attaches per-content-block cache_control markers
108	// to the outbound user/assistant messages. Markers whose `messages[i].content[j]`
109	// key no longer matches a block on the outbound side are silently dropped to
110	// match the surrounding lossy-translation discipline.
111	func applyMessagesCacheControl(messages []anthropic.MessageParam, pt *AnthropicPassthrough) {
112		if pt == nil || len(pt.CacheControl) == 0 {
113			return
114		}
115		for i := range messages {
116			for j := range messages[i].Content {
117				spec, ok := pt.CacheControl[fmt.Sprintf("messages[%d].content[%d]", i, j)]
118				if !ok {
119					continue
120				}
121				sdkCC := toSDKCacheControl(spec)
122				block := &messages[i].Content[j]
123				switch {
124				case block.OfText != nil:
125					block.OfText.CacheControl = sdkCC
126				case block.OfImage != nil:
127					block.OfImage.CacheControl = sdkCC
128				case block.OfToolUse != nil:
129					block.OfToolUse.CacheControl = sdkCC
130				case block.OfToolResult != nil:
131					block.OfToolResult.CacheControl = sdkCC
132				}
133			}
134		}
135	}
136	
137	// toSDKCacheControl converts the package-local CacheControlSpec into the SDK's
138	// CacheControlEphemeralParam. Type defaults to "ephemeral" (the only value the
139	// SDK supports today); TTL is forwarded when set.
140	func toSDKCacheControl(spec CacheControlSpec) anthropic.CacheControlEphemeralParam {
141		cc := anthropic.NewCacheControlEphemeralParam()
142		if spec.TTL != "" {
143			cc.TTL = anthropic.CacheControlEphemeralTTL(spec.TTL)
144		}
145		return cc
146	}
