148	// extractSystemContent extracts text from a system message
149	func extractSystemContent(msg *openai.ChatCompletionSystemMessageParam) string {
150		if msg.Content.OfString.Value != "" {
151			return msg.Content.OfString.Value
152		}
153		var parts []string
154		for _, part := range msg.Content.OfArrayOfContentParts {
155			if part.Text != "" {
156				parts = append(parts, part.Text)
157			}
158		}
159		return strings.Join(parts, " ")
160	}
161	
162	// extractUserContent extracts text from a user message. Kept for
163	// backwards-compatibility with callers that only need the flattened text
164	// representation; userMessageBlocks is the structured form used by the
165	// outbound writer (which also preserves image blocks).
166	func extractUserContent(msg *openai.ChatCompletionUserMessageParam) string {
167		if msg.Content.OfString.Value != "" {
168			return msg.Content.OfString.Value
169		}
170		var parts []string
171		for _, part := range msg.Content.OfArrayOfContentParts {
172			if part.OfText != nil {
173				parts = append(parts, part.OfText.Text)
174			}
175		}
176		return strings.Join(parts, " ")
177	}
178	
179	// userMessageBlocks converts an OpenAI user message into a slice of Anthropic
180	// content blocks, preserving image_url parts as Anthropic image blocks. This
181	// fixes the long-standing drop where image content (OpenAI-shape OfImageURL)
182	// was flattened to an empty string by extractUserContent, causing the model to
183	// report "I don't see any image attached" on the upstream side.
184	func userMessageBlocks(msg *openai.ChatCompletionUserMessageParam) []anthropic.ContentBlockParamUnion {
185		if msg.Content.OfString.Value != "" {
186			return []anthropic.ContentBlockParamUnion{anthropic.NewTextBlock(msg.Content.OfString.Value)}
187		}
188		var blocks []anthropic.ContentBlockParamUnion
189		var textParts []string
190		flushText := func() {
191			if len(textParts) > 0 {
192				blocks = append(blocks, anthropic.NewTextBlock(strings.Join(textParts, " ")))
193				textParts = nil
194			}
195		}
196		for _, part := range msg.Content.OfArrayOfContentParts {
197			switch {
198			case part.OfText != nil:
199				textParts = append(textParts, part.OfText.Text)
200			case part.OfImageURL != nil:
201				flushText()
202				if block, ok := openAIImageURLToAnthropicBlock(part.OfImageURL.ImageURL.URL); ok {
203					blocks = append(blocks, block)
204				}
205			}
206		}
207		flushText()
208		return blocks
209	}
210	
211	// openAIImageURLToAnthropicBlock parses an OpenAI image_url value into an
212	// Anthropic image block. Both data-URI (data:image/<type>;base64,<data>) and
213	// plain URL forms are supported; unrecognised shapes are skipped.
214	func openAIImageURLToAnthropicBlock(url string) (anthropic.ContentBlockParamUnion, bool) {
215		const dataURIPrefix = "data:"
216		if strings.HasPrefix(url, dataURIPrefix) {
217			mediaType, data, ok := parseDataURI(url)
218			if !ok {
219				return anthropic.ContentBlockParamUnion{}, false
220			}
221			return anthropic.NewImageBlock(anthropic.Base64ImageSourceParam{
222				Data:      data,
223				MediaType: anthropic.Base64ImageSourceMediaType(mediaType),
224			}), true
225		}
226		if url == "" {
227			return anthropic.ContentBlockParamUnion{}, false
228		}
229		return anthropic.NewImageBlock(anthropic.URLImageSourceParam{URL: url}), true
230	}
231	
232	// parseDataURI extracts the media type and base64-encoded payload from a data
233	// URI of the form `data:<media-type>;base64,<data>`. Returns ok=false for any
234	// other shape.
235	func parseDataURI(uri string) (mediaType, data string, ok bool) {
236		const prefix = "data:"
237		if !strings.HasPrefix(uri, prefix) {
238			return "", "", false
239		}
240		rest := uri[len(prefix):]
241		comma := strings.IndexByte(rest, ',')
242		if comma < 0 {
243			return "", "", false
244		}
245		header := rest[:comma]
246		payload := rest[comma+1:]
247		if !strings.Contains(header, ";base64") {
248			return "", "", false
249		}
250		mediaType = strings.TrimSuffix(header, ";base64")
251		if mediaType == "" {
252			return "", "", false
253		}
254		return mediaType, payload, true
255	}
256	
257	// applyUserMessageImageBlocks appends image blocks captured in the passthrough
258	// to the matching user message. Indexing is user-message-only (index 0 = first
259	// user message in messages[]). When the index is out of range, images are
260	// silently dropped to match the surrounding lossy-translation discipline.
261	func applyUserMessageImageBlocks(messages []anthropic.MessageParam, pt *AnthropicPassthrough) {
262		if pt == nil || len(pt.UserMessageImageBlocks) == 0 {
263			return
264		}
265		userIdx := -1
266		for i := range messages {
267			if messages[i].Role != anthropic.MessageParamRoleUser {
268				continue
269			}
270			userIdx++
271			images, ok := pt.UserMessageImageBlocks[userIdx]
272			if !ok {
273				continue
274			}
275			for _, img := range images {
276				block, ok := buildImageBlockFromSource(img.Source)
277				if !ok {
278					continue
279				}
280				messages[i].Content = append(messages[i].Content, block)
281			}
282		}
283	}
284	
285	// applyToolResultPassthrough overwrites tool_result blocks with the passthrough
286	// payload: is_error: true is restored from pt.ToolResultErrors, and array
287	// content (text + image blocks) is restored from pt.ToolResultArrayContent.
288	// Matches by tool_use_id; missing keys leave the block as today's
289	// translation produced it.
290	func applyToolResultPassthrough(messages []anthropic.MessageParam, pt *AnthropicPassthrough) {
291		if pt == nil || (len(pt.ToolResultErrors) == 0 && len(pt.ToolResultArrayContent) == 0) {
292			return
293		}
294		for i := range messages {
295			for j := range messages[i].Content {
296				tr := messages[i].Content[j].OfToolResult
297				if tr == nil || tr.ToolUseID == "" {
298					continue
299				}
300				if isErr, ok := pt.ToolResultErrors[tr.ToolUseID]; ok && isErr {
301					tr.IsError = anthropic.Bool(true)
302				}
303				if blocks, ok := pt.ToolResultArrayContent[tr.ToolUseID]; ok && len(blocks) > 0 {
304					tr.Content = toSDKToolResultContent(blocks)
305				}
306			}
307		}
308	}
309	
310	func toSDKToolResultContent(blocks []ToolResultContentBlock) []anthropic.ToolResultBlockParamContentUnion {
311		out := make([]anthropic.ToolResultBlockParamContentUnion, 0, len(blocks))
312		for _, b := range blocks {
313			switch b.Type {
314			case "text":
315				out = append(out, anthropic.ToolResultBlockParamContentUnion{
316					OfText: &anthropic.TextBlockParam{Text: b.Text},
317				})
318			case "image":
319				if b.Source == nil {
320					continue
321				}
322				img, ok := buildImageParamFromSource(*b.Source)
323				if !ok {
324					continue
325				}
326				out = append(out, anthropic.ToolResultBlockParamContentUnion{OfImage: img})
327			}
328		}
329		return out
330	}
331	
332	// buildImageParamFromSource is the variant of buildImageBlockFromSource that
333	// returns the raw *ImageBlockParam needed by ToolResultBlockParamContentUnion
334	// (which embeds ImageBlockParam directly rather than via NewImageBlock).
335	func buildImageParamFromSource(src ImageSource) (*anthropic.ImageBlockParam, bool) {
336		switch src.Type {
337		case "base64":
338			if src.Data == "" || src.MediaType == "" {
339				return nil, false
340			}
341			return &anthropic.ImageBlockParam{
342				Source: anthropic.ImageBlockParamSourceUnion{
343					OfBase64: &anthropic.Base64ImageSourceParam{
344						Data:      src.Data,
345						MediaType: anthropic.Base64ImageSourceMediaType(src.MediaType),
346					},
347				},
348			}, true
349		case "url":
350			if src.URL == "" {
351				return nil, false
352			}
353			return &anthropic.ImageBlockParam{
354				Source: anthropic.ImageBlockParamSourceUnion{
355					OfURL: &anthropic.URLImageSourceParam{URL: src.URL},
356				},
357			}, true
358		}
359		return nil, false
360	}
361	
362	func buildImageBlockFromSource(src ImageSource) (anthropic.ContentBlockParamUnion, bool) {
363		switch src.Type {
364		case "base64":
365			if src.Data == "" || src.MediaType == "" {
366				return anthropic.ContentBlockParamUnion{}, false
367			}
368			return anthropic.NewImageBlock(anthropic.Base64ImageSourceParam{
369				Data:      src.Data,
370				MediaType: anthropic.Base64ImageSourceMediaType(src.MediaType),
371			}), true
372		case "url":
373			if src.URL == "" {
374				return anthropic.ContentBlockParamUnion{}, false
375			}
376			return anthropic.NewImageBlock(anthropic.URLImageSourceParam{URL: src.URL}), true
377		}
378		return anthropic.ContentBlockParamUnion{}, false
379	}
380	
381	// extractAssistantContent extracts text from an assistant message
382	func extractAssistantContent(msg *openai.ChatCompletionAssistantMessageParam) string {
383		if msg.Content.OfString.Value != "" {
384			return msg.Content.OfString.Value
385		}
386		var parts []string
387		for _, part := range msg.Content.OfArrayOfContentParts {
388			if part.OfText != nil {
389				parts = append(parts, part.OfText.Text)
390			}
391		}
392		return strings.Join(parts, " ")
393	}
394	
395	func buildAnthropicMessages(
396		messages []openai.ChatCompletionMessageParamUnion,
397	) (string, []anthropic.MessageParam, error) {
398		var systemPrompt string
399		var anthropicMessages []anthropic.MessageParam
400	
401		for _, msg := range messages {
402			switch {
403			case msg.OfSystem != nil:
404				systemPrompt = extractSystemContent(msg.OfSystem)
405			case msg.OfUser != nil:
406				blocks := userMessageBlocks(msg.OfUser)
407				if len(blocks) > 0 {
408					anthropicMessages = append(anthropicMessages, anthropic.NewUserMessage(blocks...))
409				}
410			case msg.OfAssistant != nil:
411				blocks, err := assistantContentBlocks(msg.OfAssistant)
412				if err != nil {
413					return "", nil, err
414				}
415				if len(blocks) > 0 {
416					anthropicMessages = append(anthropicMessages, anthropic.NewAssistantMessage(blocks...))
417				}
418			case msg.OfTool != nil:
419				toolUseID := strings.TrimSpace(msg.OfTool.ToolCallID)
420				if toolUseID == "" {
421					return "", nil, fmt.Errorf("tool message missing tool_call_id")
422				}
423				content := extractToolMessageContent(msg.OfTool)
424				anthropicMessages = append(anthropicMessages, anthropic.NewUserMessage(
425					anthropic.NewToolResultBlock(toolUseID, content, false),
426				))
427			default:
428				logging.Debugf("Skipping unsupported OpenAI message role in Anthropic conversion")
429			}
430		}
431	
432		return systemPrompt, anthropicMessages, nil
433	}
434	
435	func extractToolMessageContent(msg *openai.ChatCompletionToolMessageParam) string {
436		if msg.Content.OfString.Value != "" {
437			return msg.Content.OfString.Value
438		}
439		var parts []string
440		for _, part := range msg.Content.OfArrayOfContentParts {
441			if part.Text != "" {
442				parts = append(parts, part.Text)
443			}
444		}
445		return strings.Join(parts, " ")
446	}
447	
448	func assistantContentBlocks(
449		msg *openai.ChatCompletionAssistantMessageParam,
450	) ([]anthropic.ContentBlockParamUnion, error) {
451		var blocks []anthropic.ContentBlockParamUnion
452	
453		content := extractAssistantContent(msg)
454		if content != "" {
455			blocks = append(blocks, anthropic.NewTextBlock(content))
456		}
457	
458		for _, toolCall := range msg.ToolCalls {
459			toolUseID := strings.TrimSpace(toolCall.ID)
460			if toolUseID == "" {
461				return nil, fmt.Errorf("assistant tool_call missing id")
462			}
463			name := strings.TrimSpace(toolCall.Function.Name)
464			if name == "" {
465				return nil, fmt.Errorf("assistant tool_call %s missing function name", toolUseID)
466			}
467			input, err := parseToolCallArguments(toolCall.Function.Arguments)
468			if err != nil {
469				return nil, fmt.Errorf("assistant tool_call %s: %w", toolUseID, err)
470			}
471			blocks = append(blocks, anthropic.NewToolUseBlock(toolUseID, input, name))
472		}
473	
474		return blocks, nil
475	}
476	
477	func parseToolCallArguments(arguments string) (any, error) {
478		trimmed := strings.TrimSpace(arguments)
479		if trimmed == "" {
480			return map[string]any{}, nil
481		}
482		var parsed any
483		if err := json.Unmarshal([]byte(trimmed), &parsed); err != nil {
484			return nil, fmt.Errorf("invalid tool arguments JSON: %w", err)
485		}
486		return parsed, nil
487	}
488	
489	func applyOpenAIToolsToAnthropicParams(
490		params *anthropic.MessageNewParams,
491		openAIRequest *openai.ChatCompletionNewParams,
492	) error {
493		if openAIRequest == nil {
494			return nil
495		}
496	
497		if len(openAIRequest.Tools) > 0 {
498			tools, err := openAIToolsToAnthropic(openAIRequest.Tools)
499			if err != nil {
500				return err
501			}
502			params.Tools = tools
503		}
504	
505		toolChoice, hasChoice := openAIToolChoiceToAnthropic(openAIRequest.ToolChoice)
506		if hasChoice {
507			params.ToolChoice = toolChoice
508		}
509		return nil
510	}
511	
512	func openAIToolsToAnthropic(tools []openai.ChatCompletionToolParam) ([]anthropic.ToolUnionParam, error) {
513		result := make([]anthropic.ToolUnionParam, 0, len(tools))
514		for index, tool := range tools {
515			if tool.Type != "" && tool.Type != "function" {
516				logging.Debugf("Skipping non-function OpenAI tool type %q at index %d", tool.Type, index)
517				continue
518			}
519			name := strings.TrimSpace(tool.Function.Name)
520			if name == "" {
521				return nil, fmt.Errorf("tools[%d]: function name is required", index)
522			}
523	
524			inputSchema, err := functionParametersToAnthropicSchema(tool.Function.Parameters)
525			if err != nil {
526				return nil, fmt.Errorf("tools[%d] (%s): %w", index, name, err)
527			}
528	
529			toolParam := anthropic.ToolParam{
530				Name:        name,
531				InputSchema: inputSchema,
532				Type:        anthropic.ToolTypeCustom,
533			}
534			if desc := strings.TrimSpace(tool.Function.Description.Value); desc != "" {
535				toolParam.Description = anthropic.String(desc)
536			}
537			result = append(result, anthropic.ToolUnionParam{OfTool: &toolParam})
538		}
539		return result, nil
540	}
541	
542	func functionParametersToAnthropicSchema(
543		parameters openai.FunctionParameters,
544	) (anthropic.ToolInputSchemaParam, error) {
545		schema := anthropic.ToolInputSchemaParam{
546			Type: "object",
547		}
548		if parameters == nil {
549			return schema, nil
550		}
551	
552		raw, err := json.Marshal(parameters)
553		if err != nil {
554			return schema, fmt.Errorf("marshal function parameters: %w", err)
555		}
556		if err := json.Unmarshal(raw, &schema); err != nil {
557			return schema, fmt.Errorf("parse function parameters: %w", err)
558		}
559		if schema.Type == "" {
560			schema.Type = "object"
561		}
562		return schema, nil
563	}
564	
565	func openAIToolChoiceToAnthropic(
566		choice openai.ChatCompletionToolChoiceOptionUnionParam,
567	) (anthropic.ToolChoiceUnionParam, bool) {
568		if !param.IsOmitted(choice.OfAuto) {
569			value := strings.TrimSpace(choice.OfAuto.Value)
570			switch value {
571			case "", "auto":
572				return anthropic.ToolChoiceUnionParam{
573					OfAuto: &anthropic.ToolChoiceAutoParam{},
574				}, true
575			case "none":
576				none := anthropic.NewToolChoiceNoneParam()
577				return anthropic.ToolChoiceUnionParam{OfNone: &none}, true
578			case "required", "any":
579				return anthropic.ToolChoiceUnionParam{
580					OfAny: &anthropic.ToolChoiceAnyParam{},
581				}, true
582			default:
583				logging.Debugf("Unknown OpenAI tool_choice auto value %q, defaulting to auto", value)
584				return anthropic.ToolChoiceUnionParam{
585					OfAuto: &anthropic.ToolChoiceAutoParam{},
586				}, true
587			}
588		}
589	
590		if choice.OfChatCompletionNamedToolChoice != nil {
591			name := strings.TrimSpace(choice.OfChatCompletionNamedToolChoice.Function.Name)
592			if name == "" {
593				return anthropic.ToolChoiceUnionParam{}, false
594			}
595			return anthropic.ToolChoiceParamOfTool(name), true
596		}
597	
598		return anthropic.ToolChoiceUnionParam{}, false
599	}
