1	package imagegen
2	
3	import (
4		"bytes"
5		"context"
6		"encoding/json"
7		"fmt"
8		"io"
9		"net/http"
10		"time"
11	
12		"github.com/vllm-project/semantic-router/src/semantic-router/pkg/config"
13	)
14	
15	// OpenAIBackend implements the Backend interface for OpenAI image generation
16	type OpenAIBackend struct {
17		baseURL    string
18		apiKey     string
19		model      string
20		quality    string
21		style      string
22		httpClient *http.Client
23	}
24	
25	// NewOpenAIBackend creates a new OpenAI image generation backend
26	func NewOpenAIBackend(cfg *config.ImageGenPluginConfig) (Backend, error) {
27		openaiConfig, err := cfg.OpenAIBackendConfig()
28		if err != nil {
29			return nil, fmt.Errorf("invalid backend_config for openai: %w", err)
30		}
31	
32		if openaiConfig.APIKey == "" {
33			return nil, fmt.Errorf("api_key is required for openai backend")
34		}
35	
36		baseURL := openaiConfig.BaseURL
37		if baseURL == "" {
38			baseURL = "https://api.openai.com"
39		}
40	
41		timeout := time.Duration(cfg.TimeoutSeconds) * time.Second
42		if timeout == 0 {
43			timeout = 60 * time.Second
44		}
45	
46		model := openaiConfig.Model
47		if model == "" {
48			model = "gpt-image-1"
49		}
50	
51		return &OpenAIBackend{
52			baseURL: baseURL,
53			apiKey:  openaiConfig.APIKey,
54			model:   model,
55			quality: openaiConfig.Quality,
56			style:   openaiConfig.Style,
57			httpClient: &http.Client{
58				Timeout: timeout,
59			},
60		}, nil
61	}
62	
63	// Name returns the backend name
64	func (b *OpenAIBackend) Name() string {
65		return "openai"
66	}
67	
68	// GenerateImage generates an image using OpenAI's image generation API
69	func (b *OpenAIBackend) GenerateImage(ctx context.Context, req *GenerateRequest) (*GenerateResponse, error) {
70		// Build OpenAI request
71		openaiReq := openAIImageRequest{
72			Model:  b.model,
73			Prompt: req.Prompt,
74			N:      1,
75			Size:   fmt.Sprintf("%dx%d", getIntOrDefault(req.Width, 1024), getIntOrDefault(req.Height, 1024)),
76		}
77	
78		if req.Model != "" {
79			openaiReq.Model = req.Model
80		}
81	
82		if req.Quality != "" {
