// vLLM-Omni API types
type vllmOmniRequest struct {
	Messages  []vllmOmniMessage  `json:"messages"`
	Model     string             `json:"model,omitempty"`
	ExtraBody *vllmOmniExtraBody `json:"extra_body,omitempty"`
