1	package extproc
2	
3	import (
4		"context"
5		"encoding/json"
6		"errors"
7	
8		core "github.com/envoyproxy/go-control-plane/envoy/config/core/v3"
9		ext_proc "github.com/envoyproxy/go-control-plane/envoy/service/ext_proc/v3"
10		typev3 "github.com/envoyproxy/go-control-plane/envoy/type/v3"
11		"github.com/openai/openai-go"
12		"github.com/tidwall/sjson"
13	
14		"github.com/vllm-project/semantic-router/src/semantic-router/pkg/observability/logging"
15		"github.com/vllm-project/semantic-router/src/semantic-router/pkg/responseapi"
16		"github.com/vllm-project/semantic-router/src/semantic-router/pkg/responsestore"
17	)
18	
19	// ResponseAPIFilter handles Response API request/response translation.
20	// It translates /v1/responses requests to /v1/chat/completions format
21	// and translates responses back, managing conversation history via previous_response_id.
22	type ResponseAPIFilter struct {
23		store      responsestore.ResponseStore
24		translator *responseapi.Translator
25		enabled    bool
26	}
27	
28	// NewResponseAPIFilter creates a new Response API filter.
29	func NewResponseAPIFilter(store responsestore.ResponseStore) *ResponseAPIFilter {
30		return &ResponseAPIFilter{
31			store:      store,
32			translator: responseapi.NewTranslator(),
33			enabled:    store != nil && store.IsEnabled(),
34		}
35	}
36	
37	// IsEnabled returns whether Response API is enabled.
38	func (f *ResponseAPIFilter) IsEnabled() bool {
39		return f.enabled
40	}
41	
42	// ResponseAPIContext holds context for a Response API request during processing.
43	type ResponseAPIContext struct {
44		// IsResponseAPIRequest indicates this is a /v1/responses request
45		IsResponseAPIRequest bool
46	
47		// OriginalRequest is the parsed Response API request
48		OriginalRequest *responseapi.ResponseAPIRequest
49	
50		// PreviousResponseID from the request (for conversation chaining)
51		PreviousResponseID string
52	
53		// ConversationHistory fetched from store
54		ConversationHistory []*responseapi.StoredResponse
55	
56		// GeneratedResponseID is the ID generated for this response
57		GeneratedResponseID string
58	
59		// ConversationID is the determined ConversationID for this request.
60		// Set early during TranslateRequest to ensure consistent tracking.
61		// Sources (in priority order):
62		//   1. Request's conversation_id field
63		//   2. First response in conversation chain (via previous_response_id)
64		//   3. Newly generated (for new conversations)
65		ConversationID string
66	
67		// TranslatedBody is the Chat Completions request body after translation
68		TranslatedBody []byte
69	
70		// HasImageGenerationTool is true when the request includes
71		// tools: [{"type": "image_generation"}]. This signals that the client
72		// explicitly requests image generation capability.
73		HasImageGenerationTool bool
74	
75		// ImageGenToolParams holds the parameters from the image_generation tool
76		// definition (model, quality, size, output_format, background, action).
77		// Non-nil only when HasImageGenerationTool is true.
78		ImageGenToolParams *responseapi.ImageGenerationToolParams
79	}
80	
81	// detectImageGenTool scans the request tools for an image_generation entry and
82	// populates the context accordingly.
83	func detectImageGenTool(req *responseapi.ResponseAPIRequest, respCtx *ResponseAPIContext) {
84		for i := range req.Tools {
85			if req.Tools[i].Type == responseapi.ToolTypeImageGeneration {
86				respCtx.HasImageGenerationTool = true
87				respCtx.ImageGenToolParams = req.Tools[i].ExtractImageGenParams()
88				if respCtx.ImageGenToolParams != nil {
89					logging.Debugf("Response API: image_generation tool (model=%s, size=%s)", respCtx.ImageGenToolParams.Model, respCtx.ImageGenToolParams.Size)
90				}
91				return
92			}
93		}
94	}
95	
96	// TranslateRequest translates a Response API request to Chat Completions format.
97	// Returns the translated request body and context, or nil if not a Response API request.
98	func (f *ResponseAPIFilter) TranslateRequest(ctx context.Context, body []byte) (*ResponseAPIContext, []byte, error) {
99		if !f.enabled {
100			return nil, nil, nil
101		}
102	
103		var req responseapi.ResponseAPIRequest
104		if err := json.Unmarshal(body, &req); err != nil {
105			return nil, nil, nil
106		}
107	
108		if len(req.Input) == 0 {
109			return nil, nil, nil
110		}
111	
112		respCtx := &ResponseAPIContext{
113			IsResponseAPIRequest: true,
114			OriginalRequest:      &req,
115			PreviousResponseID:   req.PreviousResponseID,
116			GeneratedResponseID:  responseapi.GenerateResponseID(),
117		}
118	
119		detectImageGenTool(&req, respCtx)
120	
121		if req.PreviousResponseID != "" {
122			history, err := f.store.GetConversationChain(ctx, req.PreviousResponseID)
123			if err != nil && !errors.Is(err, responsestore.ErrNotFound) {
124				logging.Warnf("Failed to fetch conversation history for %s: %v", req.PreviousResponseID, err)
125			}
126			respCtx.ConversationHistory = history
127		}
128	
129		respCtx.ConversationID = f.determineConversationID(&req, respCtx.ConversationHistory)
130	
131		completionReq, err := f.translator.TranslateToCompletionRequest(&req, respCtx.ConversationHistory)
132		if err != nil {
133			return nil, nil, err
134		}
135	
136		translatedBody, err := json.Marshal(completionReq)
137		if err != nil {
138			return nil, nil, err
139		}
140	
141		translatedBody = injectResponseAPITransportFields(translatedBody, &req)
142	
143		respCtx.TranslatedBody = translatedBody
144	
145		return respCtx, translatedBody, nil
146	}
147	
148	func injectResponseAPITransportFields(
149		body []byte,
150		req *responseapi.ResponseAPIRequest,
151	) []byte {
152		if req.Stream {
153			if updated, err := sjson.SetBytes(body, "stream", true); err == nil {
154				body = updated
155			}
156		}
157		if len(req.Metadata) > 0 {
158			if updated, err := sjson.SetBytes(
159				body,
160				"metadata",
161				req.Metadata,
162			); err == nil {
163				body = updated
164			}
165		}
166		return body
167	}
168	
169	// TranslateResponse translates a Chat Completions response back to Response API format.
170	func (f *ResponseAPIFilter) TranslateResponse(ctx context.Context, respCtx *ResponseAPIContext, body []byte) ([]byte, error) {
171		if !f.enabled || respCtx == nil || !respCtx.IsResponseAPIRequest {
172			return body, nil
173		}
174	
175		if isResponseAPIErrorBody(body) {
176			logging.Warnf("Response API: Backend returned error response, passing through")
177			return body, nil
178		}
179	
180		completionResp, ok := parseChatCompletionResponse(body)
181		if !ok {
182			return body, nil
183		}
184	
185		responseAPIResp := f.buildTranslatedResponse(respCtx, completionResp)
186		f.maybeStoreTranslatedResponse(ctx, respCtx, responseAPIResp)
187	
188		translatedBody, ok := marshalTranslatedResponse(body, responseAPIResp)
189		if !ok {
190			return body, nil
191		}
192	
193		return translatedBody, nil
194	}
195	
196	func isResponseAPIErrorBody(body []byte) bool {
197		var errorCheck map[string]interface{}
198		if err := json.Unmarshal(body, &errorCheck); err != nil {
199			return false
200		}
201		_, hasError := errorCheck["error"]
202		return hasError
203	}
204	
205	func parseChatCompletionResponse(body []byte) (*openai.ChatCompletion, bool) {
206		var completionResp openai.ChatCompletion
207		if err := json.Unmarshal(body, &completionResp); err != nil {
208			logging.Errorf("Response API: Failed to parse completion response: %v", err)
209			return nil, false
210		}
211	
212		if completionResp.ID == "" && len(completionResp.Choices) == 0 {
213			logging.Warnf("Response API: Invalid completion response (no id or choices), passing through")
214			return nil, false
215		}
216	
217		return &completionResp, true
218	}
219	
220	func (f *ResponseAPIFilter) buildTranslatedResponse(
221		respCtx *ResponseAPIContext,
222		completionResp *openai.ChatCompletion,
223	) *responseapi.ResponseAPIResponse {
224		responseAPIResp := f.translator.TranslateToResponseAPIResponse(
225			respCtx.OriginalRequest,
226			completionResp,
227			respCtx.PreviousResponseID,
228		)
229	
230		responseAPIResp.ID = respCtx.GeneratedResponseID
231	
232		if respCtx.ConversationID != "" {
233			responseAPIResp.ConversationID = respCtx.ConversationID
234		}
235	
236		return responseAPIResp
237	}
238	
239	func (f *ResponseAPIFilter) maybeStoreTranslatedResponse(
240		ctx context.Context,
241		respCtx *ResponseAPIContext,
242		responseAPIResp *responseapi.ResponseAPIResponse,
243	) {
244		shouldStore := respCtx.OriginalRequest.Store == nil || *respCtx.OriginalRequest.Store
245		if shouldStore && f.store.IsEnabled() {
246			stored := f.toStoredResponse(respCtx.OriginalRequest, responseAPIResp)
247			if err := f.store.StoreResponse(ctx, stored); err != nil {
248				logging.Warnf("Response API: Failed to store response: %v", err)
249			}
250		}
251	}
252	
253	func marshalTranslatedResponse(
254		originalBody []byte,
255		responseAPIResp *responseapi.ResponseAPIResponse,
256	) ([]byte, bool) {
257		translatedBody, err := json.Marshal(responseAPIResp)
258		if err != nil {
259			logging.Errorf("Response API: Failed to marshal response: %v", err)
260			return originalBody, false
261		}
262	
263		return translatedBody, true
264	}
265	
266	// toStoredResponse converts request and response to a StoredResponse for storage.
267	func (f *ResponseAPIFilter) toStoredResponse(req *responseapi.ResponseAPIRequest, resp *responseapi.ResponseAPIResponse) *responseapi.StoredResponse {
268		inputItems := parseResponseAPIInputItems(req.Input)
269	
270		return &responseapi.StoredResponse{
271			ID:                 resp.ID,
272			Object:             resp.Object,
273			CreatedAt:          resp.CreatedAt,
274			Model:              resp.Model,
275			Status:             resp.Status,
276			Input:              inputItems,
277			Output:             resp.Output,
278			OutputText:         resp.OutputText,
279			PreviousResponseID: resp.PreviousResponseID,
280			ConversationID:     resp.ConversationID,
281			Usage:              resp.Usage,
282			Instructions:       resp.Instructions,
283			Metadata:           resp.Metadata,
284		}
285	}
286	
287	func parseResponseAPIInputItems(input json.RawMessage) []responseapi.InputItem {
288		if len(input) == 0 {
289			return nil
290		}
291	
292		// Try parsing as array of input items first.
293		var items []responseapi.InputItem
294		if err := json.Unmarshal(input, &items); err == nil {
295			for i := range items {
296				if items[i].ID == "" {
297					items[i].ID = responseapi.GenerateItemID()
298				}
299				if items[i].Status == "" {
300					items[i].Status = responseapi.StatusCompleted
301				}
302			}
303			return items
304		}
305	
306		// Fallback: input can also be a string; store as a user message item.
307		var inputStr string
308		if err := json.Unmarshal(input, &inputStr); err == nil {
309			return []responseapi.InputItem{{
310				ID:      responseapi.GenerateItemID(),
311				Type:    responseapi.ItemTypeMessage,
312				Role:    responseapi.RoleUser,
313				Content: input,
314				Status:  responseapi.StatusCompleted,
315			}}
316		}
317	
318		return nil
319	}
320	
321	// HandleGetResponse handles GET /v1/responses/{id} requests.
322	func (f *ResponseAPIFilter) HandleGetResponse(ctx context.Context, responseID string) (*ext_proc.ProcessingResponse, error) {
323		if !f.enabled {
324			return createResponseAPIError(404, "Response API not enabled"), nil
325		}
326	
327		// Get response from store
328		stored, err := f.store.GetResponse(ctx, responseID)
329		if err != nil {
330			if errors.Is(err, responsestore.ErrNotFound) {
331				return createResponseAPIError(404, "Response not found: "+responseID), nil
332			}
333			logging.Errorf("Response API: Error getting response %s: %v", responseID, err)
334			return createResponseAPIError(500, "Error retrieving response"), nil
335		}
336	
337		// Convert to Response API format
338		resp := f.storedToResponseAPIResponse(stored)
339	
340		// Marshal response
341		body, err := json.Marshal(resp)
342		if err != nil {
343			logging.Errorf("Response API: Error marshaling response: %v", err)
344			return createResponseAPIError(500, "Error serializing response"), nil
345		}
346	
347		return createImmediateJSONResponse(200, body), nil
348	}
349	
350	// HandleDeleteResponse handles DELETE /v1/responses/{id} requests.
351	func (f *ResponseAPIFilter) HandleDeleteResponse(ctx context.Context, responseID string) (*ext_proc.ProcessingResponse, error) {
352		if !f.enabled {
353			return createResponseAPIError(404, "Response API not enabled"), nil
354		}
355	
356		// Delete response from store
357		err := f.store.DeleteResponse(ctx, responseID)
358		if err != nil {
359			if errors.Is(err, responsestore.ErrNotFound) {
360				return createResponseAPIError(404, "Response not found: "+responseID), nil
361			}
362			logging.Errorf("Response API: Error deleting response %s: %v", responseID, err)
363			return createResponseAPIError(500, "Error deleting response"), nil
364		}
365	
366		// Return deletion confirmation
367		deleteResp := responseapi.DeleteResponseResult{
368			ID:      responseID,
369			Object:  "response.deleted",
370			Deleted: true,
371		}
372	
373		body, err := json.Marshal(deleteResp)
374		if err != nil {
375			logging.Errorf("Response API: Error marshaling delete response: %v", err)
376			return createResponseAPIError(500, "Error serializing response"), nil
377		}
378	
379		return createImmediateJSONResponse(200, body), nil
380	}
381	
382	// HandleGetInputItems handles GET /v1/responses/{id}/input_items requests.
383	func (f *ResponseAPIFilter) HandleGetInputItems(ctx context.Context, responseID string) (*ext_proc.ProcessingResponse, error) {
384		if !f.enabled {
385			return createResponseAPIError(404, "Response API not enabled"), nil
386		}
387	
388		// Get response from store
389		stored, err := f.store.GetResponse(ctx, responseID)
390		if err != nil {
391			if errors.Is(err, responsestore.ErrNotFound) {
392				return createResponseAPIError(404, "Response not found: "+responseID), nil
393			}
394			logging.Errorf("Response API: Error getting response %s: %v", responseID, err)
395			return createResponseAPIError(500, "Error retrieving response"), nil
396		}
397	
398		// Build input items list from stored response
399		inputItems := f.buildInputItemsList(stored)
400	
401		// Create response with pagination structure
402		listResp := responseapi.InputItemsListResponse{
403			Object:  "list",
404			Data:    inputItems,
405			FirstID: "",
406			LastID:  "",
407			HasMore: false,
408		}
409	
410		if len(inputItems) > 0 {
411			listResp.FirstID = inputItems[0].ID
412			listResp.LastID = inputItems[len(inputItems)-1].ID
413		}
414	
415		body, err := json.Marshal(listResp)
416		if err != nil {
417			logging.Errorf("Response API: Error marshaling input items: %v", err)
418			return createResponseAPIError(500, "Error serializing response"), nil
419		}
420	
421		return createImmediateJSONResponse(200, body), nil
422	}
423	
424	// buildInputItemsList builds the input items list from a stored response.
425	func (f *ResponseAPIFilter) buildInputItemsList(stored *responseapi.StoredResponse) []responseapi.InputItem {
426		var items []responseapi.InputItem
427	
428		// Add instructions as system message if present
429		if stored.Instructions != "" {
430			contentParts := []responseapi.ContentPart{{Type: "input_text", Text: stored.Instructions}}
431			contentJSON, _ := json.Marshal(contentParts)
432			items = append(items, responseapi.InputItem{
433				ID:      responseapi.GenerateItemID(),
434				Type:    "message",
435				Role:    "system",
436				Content: contentJSON,
437				Status:  "completed",
438			})
439		}
440	
441		// Add stored input items
442		items = append(items, stored.Input...)
443	
444		return items
445	}
446	
447	// storedToResponseAPIResponse converts a StoredResponse back to ResponseAPIResponse.
448	func (f *ResponseAPIFilter) storedToResponseAPIResponse(stored *responseapi.StoredResponse) *responseapi.ResponseAPIResponse {
449		return &responseapi.ResponseAPIResponse{
450			ID:                 stored.ID,
451			Object:             "response",
452			CreatedAt:          stored.CreatedAt,
453			Model:              stored.Model,
454			Status:             stored.Status,
455			Output:             stored.Output,
456			OutputText:         stored.OutputText,
457			PreviousResponseID: stored.PreviousResponseID,
458			ConversationID:     stored.ConversationID,
459			Usage:              stored.Usage,
460			Instructions:       stored.Instructions,
461			Metadata:           stored.Metadata,
462		}
463	}
464	
465	// determineConversationID determines the ConversationID for this request.
466	// Priority order:
467	//  1. Request's conversation_id field (explicit)
468	//  2. First response in conversation chain (continuation via previous_response_id)
469	//  3. Newly generated (new conversation)
470	func (f *ResponseAPIFilter) determineConversationID(req *responseapi.ResponseAPIRequest, history []*responseapi.StoredResponse) string {
471		// Priority 1: Request explicitly provides conversation_id
472		if req.ConversationID != "" {
473			return req.ConversationID
474		}
475	
476		// Priority 2: Get from conversation history (continuation)
477		if len(history) > 0 {
478			// Find ConversationID from the first response in the chain
479			firstResponse := history[0]
480			if firstResponse.ConversationID != "" {
481				return firstResponse.ConversationID
482			}
483		}
484	
485		// Priority 3: Generate new ConversationID (new conversation)
486		return responseapi.GenerateConversationID()
487	}
488	
489	// createResponseAPIError creates an error response in OpenAI format.
490	func createResponseAPIError(statusCode int, message string) *ext_proc.ProcessingResponse {
491		errorResp := map[string]interface{}{
492			"error": map[string]interface{}{
493				"message": message,
494				"type":    "invalid_request_error",
495				"code":    statusCode,
496			},
497		}
498	
499		body, _ := json.Marshal(errorResp)
500		return createImmediateJSONResponse(statusCode, body)
501	}
502	
503	// createImmediateJSONResponse creates an immediate response with JSON body.
504	func createImmediateJSONResponse(statusCode int, body []byte) *ext_proc.ProcessingResponse {
505		return &ext_proc.ProcessingResponse{
506			Response: &ext_proc.ProcessingResponse_ImmediateResponse{
507				ImmediateResponse: &ext_proc.ImmediateResponse{
508					Status: &typev3.HttpStatus{
509						Code: statusCodeToEnumForResponseAPI(statusCode),
510					},
511					Headers: &ext_proc.HeaderMutation{
512						SetHeaders: []*core.HeaderValueOption{
513							{
514								Header: &core.HeaderValue{
515									Key:      "content-type",
516									RawValue: []byte("application/json"),
517								},
518							},
519						},
520					},
521					Body: body,
522				},
523			},
524		}
525	}
526	
527	// statusCodeToEnumForResponseAPI converts HTTP status code to Envoy enum.
528	func statusCodeToEnumForResponseAPI(statusCode int) typev3.StatusCode {
529		switch statusCode {
530		case 200:
531			return typev3.StatusCode_OK
532		case 400:
533			return typev3.StatusCode_BadRequest
534		case 404:
535			return typev3.StatusCode_NotFound
536		case 500:
537			return typev3.StatusCode_InternalServerError
538		default:
539			return typev3.StatusCode_OK
540		}
541	}
